INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40211, 'Job 12:10', 'Job', 12, 10, 'د هغۀ په لاس کښې د هر ژوندى څيز ژوند دے او د هغۀ په لاس کښې د هر بشر ساه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_10.mp3', '', 1761754199, 1761754199),
(40212, 'Job 12:11', 'Job', 12, 11, 'ولې غوږونه د خبرو معائنه نۀ کوى لکه څنګه چې ژبه د خوراک خوند معلوموى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_11.mp3', '', 1761754199, 1761754199),
(40213, 'Job 12:12', 'Job', 12, 12, 'ولې حِکمت د سپين‌ږيرو سره نۀ وى څۀ؟ ولې زيات عُمر سره پوهه نۀ راځى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_12.mp3', '', 1761754199, 1761754199),
(40214, 'Job 12:13', 'Job', 12, 13, 'حِکمت او طاقت د خُدائ پاک سره دى، د هغۀ سره رهنمائى او پوهه شته دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_13.mp3', '', 1761754199, 1761754199),
(40215, 'Job 12:14', 'Job', 12, 14, 'چې هغه څۀ وران کړى نو هيڅ څوک يې بيا نۀ شى جوړولے، او چې هغه کوم سړے قېدى کړى نو هغه خلاصېدلے نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_14.mp3', '', 1761754199, 1761754199),
(40216, 'Job 12:15', 'Job', 12, 15, 'کۀ هغه باران ايسار کړى، نو زمکه به اوچه شى، کۀ هغه اوبۀ راپرېږدى، نو اوبۀ به زمکه تباه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_15.mp3', '', 1761754199, 1761754199),
(40217, 'Job 12:16', 'Job', 12, 16, 'طاقت او حِکمت د هغۀ سره دے، دوکه خوړونکے او دوکه ورکوونکے د هغۀ د اختيار لاندې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_16.mp3', '', 1761754199, 1761754199),
(40218, 'Job 12:17', 'Job', 12, 17, 'هغه د مشرانو نه پوهه اخلى، او د قاضيانو نه کم عقلان جوړوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_17.mp3', '', 1761754199, 1761754199),
(40219, 'Job 12:18', 'Job', 12, 18, 'هغه د بادشاهانو نه اختيار واخلى، او د هغوئ نه غلامان جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_18.mp3', '', 1761754199, 1761754199),
(40220, 'Job 12:19', 'Job', 12, 19, 'هغه اِمامان شړى او اختيار ترې اخلى، او هغه طاقتور لرې کوى چې ډېر وخت يې حکومت کړے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_19.mp3', '', 1761754199, 1761754199),
(40221, 'Job 12:20', 'Job', 12, 20, 'هغه اعتبارى مشيران غلى کړى، د مشرانو نه حِکمت يوسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_20.mp3', '', 1761754199, 1761754199),
(40222, 'Job 12:21', 'Job', 12, 21, 'هغه شهزادګان سپک کړى، او هغه د زورَورو زور اوبۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_21.mp3', '', 1761754199, 1761754199),
(40223, 'Job 12:22', 'Job', 12, 22, 'هغه د قبر تيارۀ لرې کوى، او هغه تکه توره تيارۀ په رڼا بدلوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_22.mp3', '', 1761754199, 1761754199),
(40224, 'Job 12:23', 'Job', 12, 23, 'هغه قومونه تکړه کړى او بيا يې تباه کړى، هغه قومونه لوئ کړى او بيا يې پرېږدى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_23.mp3', '', 1761754199, 1761754199),
(40225, 'Job 12:24', 'Job', 12, 24, 'هغه د دُنيا د مشرانو نه پوهه ختموى، او پرې يې ږدى چې سرګردانه او پرېشانه ګرځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_24.mp3', '', 1761754199, 1761754199),
(40226, 'Job 12:25', 'Job', 12, 25, 'هغه مشران په تيارۀ کښې د ړندو په شان سرګردانه ګرځى، او د شرابى په شان يې ځنګېدلے کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_25.mp3', '', 1761754199, 1761754199),
(40227, 'Isaiah 66:1', 'Isaiah', 66, 1, 'څښتن داسې وایي: «اسمان زما تخت دی او ځمکه زما د پښو چوکۍ ده. تاسو به ماته څه ډول کور جوړ کړئ او زما د اوسېدلو ځای چېرته دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_1.mp3', '', 1761754199, 1761754199),
(40228, 'Isaiah 66:2', 'Isaiah', 66, 2, 'ما دا ټول شیان په خپل لاس پیدا کړل او هغه منځ ته راغلل. خو زه د هغه چا سره یم چې عاجز او توبه کوونکی وي او زما د کلام په وړاندې له وېرې رېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_2.mp3', '', 1761754199, 1761754199),
(40229, 'Isaiah 66:3', 'Isaiah', 66, 3, 'څوک چې د قربانۍ دپاره غویی حلالوي، هغه انسان هم قتلوي. څوک چې وری د قربانۍ دپاره حلالوي، هغه د سپي ورمېږ هم ماتوي. څوک چې د غلو دانو نذرانې ماته راوړي، هغه د خوګ وینه هم وړاندې کوي. څوک چې ماته قیمتي خوشبویي سوځوي، هغه بت ته هم عبادت کوي. څنګه چې د هغوی زړه وغواړي، هماغه کار کوي. هغوی د هغو ناوړو کارونو څخه چې د کرکې وړ دي، خوند اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_3.mp3', '', 1761754199, 1761754199),
(40230, 'Isaiah 66:4', 'Isaiah', 66, 4, 'نو زه به هم د هغوی دپاره سخت مصیبت وغواړم، داسې مصیبت چې هغوی ورنه وېریږي. ځکه کله چې ما په هغوی غږ وکړ، نو هېچا ځواب رانه کړ او کله به چې ما خبرې کولې، نو هېچا به ورته غوږ نه نیوه. خو هغوی هغه کارونه وکړل چې زما په نظر بد وو او هغه څه یې خوښ کړل چې زه پرې خوشحاله نه وم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_4.mp3', '', 1761754199, 1761754199),
(40231, 'Isaiah 66:5', 'Isaiah', 66, 5, 'ای هغو خلکو چې د څښتن د کلام څخه لړزېږئ، د هغه کلام ته غوږ ونیسئ چې وایي: «زما د نوم په خاطر ستاسو خپل خلک ستاسو نه کرکه کوي او تاسې شړي. هغوی په ملنډو تاسو ته وایي: ‹څښتن دې خپله لویي وښایي او تاسو دې وژغوري، ترڅو مونږ ستاسو خوشحالي ووینو!› خو هغوی به په خپله رسوا شي او وبه شرمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_5.mp3', '', 1761754199, 1761754199),
(40232, 'Isaiah 66:6', 'Isaiah', 66, 6, 'واورئ! هغه شورماشور چې له ښار څخه راځي او هغه غوغا چې د عبادت د ځای څخه اورېدل کیږي، دا د څښتن اواز دی چې د خپلو دښمنانو څخه بدل اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_6.mp3', '', 1761754199, 1761754199),
(40233, 'Isaiah 66:7', 'Isaiah', 66, 7, 'زما سپېڅلی ښار د هغې ښځې په شان دی چې ماشوم یې د زېږېدو له درد نه مخکې وزېږیږي، د لنګون له درد نه مخکې یې ناڅاپه زوی دې نړۍ ته راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_7.mp3', '', 1761754199, 1761754199),
(40234, 'Isaiah 66:8', 'Isaiah', 66, 8, 'ایا چا کله داسې حیرانوونکې پېښه لیدلې یا اورېدلې ده چې ناڅاپه یو هېواد په یوه ورځ کې پیدا شي؟ ایا کوم قوم په یوه شېبه کې زېږېدلی شي؟ خو په هغه شېبه کې چې په صهیون باندې د لنګون درد پیل شو، ماشومان یې دې نړۍ ته راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_8.mp3', '', 1761754199, 1761754199),
(40235, 'Isaiah 66:9', 'Isaiah', 66, 9, 'ایا فکر کوئ کله چې زه د یوې ښځې خېټه خلاصه کړم او په همدې شېبه کې یې پرېنږدم چې ماشوم یې وزېږیږي؟ نه، زه هېڅکله داسې کار نه کوم.» ستاسو څښتن خدای داسې ویلي دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_9.mp3', '', 1761754199, 1761754199),
(40236, 'Isaiah 66:10', 'Isaiah', 66, 10, 'ای هغو خلکو چې کوئ مینه د اورشلیم سره ای هغو خلکو چې کوئ ویر د هغه دپاره خو اوس خوشحال اوسئ او شریک شئ د هغه په خوشحالۍ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_10.mp3', '', 1761754199, 1761754199),
(40237, 'Isaiah 66:11', 'Isaiah', 66, 11, 'لکه څنګه چې خوند اخلي ماشوم د خپلې مور د سینې له شیدو تاسو به هم شئ برخمن د اورشلیم له نعمتونو څخه او خوند به واخلئ د هغه له جلاله څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_11.mp3', '', 1761754199, 1761754199),
(40238, 'Isaiah 66:12', 'Isaiah', 66, 12, 'څښتن داسې وایي: «ګورئ، زه به نېکمرغي او سلامتي د سیند په شان په اورشلیم کې جاري کړم او د نورو قومونو شتمني به هغه ته د خوړ د سېلاب په شان راروانه کړم. تاسو به د داسې ماشوم په شان یئ چې د مور له خوا شیدې ورکول کیږي، په خپله غېږه کې یې وړي او د مینې نه ډک چلند ورسره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_12.mp3', '', 1761754199, 1761754199),
(40239, 'Isaiah 66:13', 'Isaiah', 66, 13, 'لکه څنګه چې یوه مور خپل ماشوم ته تسلي ورکوي، نو زه به هم تاسو ته په اورشلیم کې تسلي درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_13.mp3', '', 1761754199, 1761754199),
(40240, 'Isaiah 66:14', 'Isaiah', 66, 14, 'کله چې تاسو دا پېښې وګورئ، نو خوشحاله به شئ. ستاسو بدن به د شنو واښو په شان وده وکړي. نو هغه وخت به پوه شئ چې زه څښتن د خپلو خدمتګارانو سره مرسته کوم او خپلو دښمنانو ته خپل قهر ښایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_14.mp3', '', 1761754199, 1761754199),
(40241, 'Isaiah 66:15', 'Isaiah', 66, 15, 'ګورئ، څښتن د اور سره راروان دی او د هغه جنګي ګاډۍ د توفان په شان غړمبیږي. هغه به په ډېر قهر او د اور د شغلو په شان په سختو رټلو سره خپلو دښمنانو ته سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_15.mp3', '', 1761754199, 1761754199),
(40242, 'Isaiah 66:16', 'Isaiah', 66, 16, 'ځکه هغه به په اور او خپلې تورې د نړۍ ټولو خلکو ته سزا ورکړي او ډېر خلک به د هغه د لاسه ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_16.mp3', '', 1761754199, 1761754199),
(40243, 'Isaiah 66:17', 'Isaiah', 66, 17, 'څښتن داسې وایي: «هغه خلک به ټول یوځای له منځه لاړ شي چې خپل ځانونه سپېڅلي او پاکوي، یوازې د دې دپاره باغونو ته ځي چې د بتانو عبادت وکړي او د خوګ غوښه، موږکان او نور حرام شیان وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_17.mp3', '', 1761754199, 1761754199),
(40244, 'Isaiah 66:18', 'Isaiah', 66, 18, 'زه د هغوی د خیالونو او کړنو څخه خبر یم. زه راځم د دې دپاره چې د ټولو قومونو او ژبو خلک سره راغونډ کړم. کله چې هغوی راشي، نو زما جلال به وویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_18.mp3', '', 1761754199, 1761754199),
(40245, 'Isaiah 66:19', 'Isaiah', 66, 19, 'او زه به د هغوی په منځ کې یو زورور کار وکړم. له دې خلکو نه به ځینې ژوندي پرېږدم او هغوی به دغو ځایونو ته ولېږم: هسپانیې، پول، لود چې په غشو ویشتلو کې مهارت لري، توبال او یونان او لېرې هېوادونو ته چې زما د شهرت څخه خبر نه دي او زما لویي یې نه ده لیدلې. هغوی به د دغو هېوادنو خلکو ته زما لویي اعلان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_19.mp3', '', 1761754199, 1761754199),
(40246, 'Isaiah 66:20', 'Isaiah', 66, 20, 'هغوی به ستاسو ټول اسراییلي ورونه له نورو قومونو څخه بېرته راولي. هغوی به دغه اسراییلي ورونه په اسونو، قچرو، اوښانو، جنګي او عادي ګاډیو کې سپاره زما سپېڅلي غره اورشلیم ته راولي او ماته به یې د یوې نذرانې په توګه وړاندې کړي، لکه څنګه چې اسراییلیان په پاکو لوښو کې د غلو دانو نذرانې زما د عبادت ځای ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_20.mp3', '', 1761754199, 1761754199),
(40247, 'Isaiah 66:21', 'Isaiah', 66, 21, 'همدارنګه زه به د هغوی نه ځینې د کاهنانو په توګه وټاکم او ځینې د لاویانو په توګه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_21.mp3', '', 1761754199, 1761754199),
(40248, 'Isaiah 66:22', 'Isaiah', 66, 22, 'څښتن داسې وایي: «لکه څنګه چې نوي اسمانونه او نوې ځمکه چې زه یې جوړوم زما په حضور کې به تلپاتې وي، همداسې به ستاسو اولاده او ستاسو نوم تلپاتې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_22.mp3', '', 1761754199, 1761754199),
(40249, 'Isaiah 66:23', 'Isaiah', 66, 23, 'د هرې نوې میاشتې په اختر او همدارنګه د سبت په هره ورځ به د نړۍ ټول خلک زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_23.mp3', '', 1761754199, 1761754199),
(40250, 'Isaiah 66:24', 'Isaiah', 66, 24, 'کله چې هغوی د اورشلیم څخه ووځي، نو د هغو خلکو مړي به وویني چې زما په وړاندې یې سرغړونه کړې وه. کوم چینجي چې د هغوی مړي خوري، هېڅکله به نه مري او کوم اور چې هغوی سوځوي، هېڅکله به نه مړ کیږي. ټول خلک به هغوی ته د کرکې په سترګه ګوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah66_verse_24.mp3', '', 1761754199, 1761754199),
(40251, 'Job 34:1', 'Job', 34, 1, 'نو اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_1.mp3', '', 1761754199, 1761754199),
(40252, 'Job 34:2', 'Job', 34, 2, '”اے عقلمندو سړو، زما خبره واورئ، اے هوښيارانو ما ته غوږ ونيسئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_2.mp3', '', 1761754199, 1761754199),
(40253, 'Job 34:3', 'Job', 34, 3, 'ځکه چې غوږونه خبرې داسې معلوموى لکه څنګه چې ژبه د خوراک په خوند پوهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_3.mp3', '', 1761754199, 1761754199),
(40254, 'Job 34:4', 'Job', 34, 4, 'راځئ چې د دې پته ولګوو چې څۀ صحيح دى، راځئ چې ښۀ څيزونه زده کړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_4.mp3', '', 1761754199, 1761754199),
(40255, 'Job 34:5', 'Job', 34, 5, 'ځکه چې ايُوب وئيلى دى چې زۀ بې‌ګناه يم، او خُدائ پاک زما سره اِنصاف نۀ کوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_5.mp3', '', 1761754199, 1761754199),
(40256, 'Job 34:6', 'Job', 34, 6, 'زۀ بې‌ګناه يم خو دروغژن ګڼلے شم، په ما کښې څۀ غلطى نشته، خو زما د زخم علاج نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_6.mp3', '', 1761754199, 1761754199),
(40257, 'Job 34:7', 'Job', 34, 7, 'د ايُوب په شان څوک شته، چې په چا کښې زره غوندې ادب هم نۀ وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_7.mp3', '', 1761754199, 1761754199),
(40258, 'Job 34:8', 'Job', 34, 8, 'چې هغه د بدعملو سره ملګرتيا کوى او د بدمعاشانو سره ګرځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_8.mp3', '', 1761754199, 1761754199),
(40259, 'Job 34:9', 'Job', 34, 9, 'نو هغۀ دا هم وئيلى دى چې، ”د خُدائ پاک د راضى کولو څۀ فائده ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_9.mp3', '', 1761754199, 1761754199),
(40260, 'Job 34:10', 'Job', 34, 10, 'نو چې څوک عقل لرئ نو زما خبره واورئ، هر چا ته پته ده چې خُدائ پاک بدى نۀ کوى، او د قادر خُدائ دپاره ممکن نۀ دى چې هغه غلطى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_10.mp3', '', 1761754199, 1761754199),
(40261, 'Job 34:11', 'Job', 34, 11, 'ځکه چې هغه د عملونو په مطابق خلقو له بدله ورکوى، او هغه شان سلوک ورسره کوى چې څنګه يې حقدار وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_11.mp3', '', 1761754199, 1761754199),
(40262, 'Job 34:12', 'Job', 34, 12, 'بې‌شکه، خُدائ پاک به بد عمل نۀ کوى، او قادر خُدائ د هيچا سره بې‌اِنصافى نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_12.mp3', '', 1761754199, 1761754199),
(40263, 'Job 34:13', 'Job', 34, 13, 'هغۀ له د زمکې اختيار چا ورکړے دے، او دا ټوله دُنيا په خپل ځائ چا لګولې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_13.mp3', '', 1761754199, 1761754199),
(40264, 'Job 34:14', 'Job', 34, 14, 'کۀ خُدائ پاک د خلقو نه روح واخلى، او د ژوند ساه ترې نه واخلى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_14.mp3', '', 1761754199, 1761754199),
(40265, 'Job 34:15', 'Job', 34, 15, 'ټول انسانان به ختم شى، او ټول بنى آدم به خاورو ته واپس کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_15.mp3', '', 1761754199, 1761754199),
(40266, 'Job 34:16', 'Job', 34, 16, 'کۀ تاسو پوهه لرئ، نو دا خبره واورئ، زۀ چې څۀ وايم نو هغې ته غوږ کېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_16.mp3', '', 1761754199, 1761754199),
(40267, 'Job 34:17', 'Job', 34, 17, 'چې خُدائ پاک پخپله اِنصاف نۀ کوى نو بيا هغه څنګه دُنيا چلولے شى؟ تاسو به هغه لويه هستى رد کوئ څوک چې صادق دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_17.mp3', '', 1761754199, 1761754199),
(40268, 'Job 34:18', 'Job', 34, 18, 'څوک چې بادشاه ته وائى چې تۀ بې‌کاره يې، او مشر ته وائى چې تۀ بدعمله يې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_18.mp3', '', 1761754199, 1761754199),
(40269, 'Job 34:19', 'Job', 34, 19, 'څوک چې د حکمرانانو طرفدارى نۀ کوى، او د مالدارو خلقو طرفدارى د غريبانانو نه زياته نۀ کوى، ځکه چې ټول هغۀ پېدا کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_19.mp3', '', 1761754199, 1761754199),
(40270, 'Job 34:20', 'Job', 34, 20, 'يو کس د شپې اچانک مړ کېدے شى، خُدائ پاک خلق ووهى او هغوئ هلاک شى، خُدائ پاک طاقتور خلق هم په آسانۍ سره وژلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_20.mp3', '', 1761754199, 1761754199),
(40271, 'Job 34:21', 'Job', 34, 21, 'ځکه چې د هغۀ نظر د بنى آدم په عمل باندې دے، او هغه د هغوئ هر قدم ته ګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_21.mp3', '', 1761754199, 1761754199),
(40272, 'Job 34:22', 'Job', 34, 22, 'داسې تکه توره تيارۀ نشته چرته چې بدعمله خلق خپل ځانونه د هغۀ نه پټ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_22.mp3', '', 1761754199, 1761754199),
(40273, 'Job 34:23', 'Job', 34, 23, 'مونږ وخت نۀ مقرروو چې کله به د خُدائ پاک په وړاندې د عدالت دپاره راځو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_23.mp3', '', 1761754199, 1761754199),
(40274, 'Job 34:24', 'Job', 34, 24, 'هغه د تپوس نه بغېر طاقتور راګزار کړى، او د هغوئ په ځائ کښې نور مقرر کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_24.mp3', '', 1761754199, 1761754199),
(40275, 'Job 34:25', 'Job', 34, 25, 'هغه د هغوئ په کارونو خبر دے، هغه يې په شپه کښې لرې کړى او هغوئ تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_25.mp3', '', 1761754199, 1761754199),
(40276, 'Job 34:26', 'Job', 34, 26, 'د هغوئ د بدعملۍ په وجه يې تباه کړى چې د نورو دپاره د عبرت سبب جوړ شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_26.mp3', '', 1761754199, 1761754199),
(40277, 'Job 34:27', 'Job', 34, 27, 'ځکه چې هغوئ د هغۀ د تابعدارۍ نه اوړى، او د هغۀ په حُکمونو باندې عمل نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_27.mp3', '', 1761754199, 1761754199),
(40278, 'Job 34:28', 'Job', 34, 28, 'نو هغوئ غريبانان فرياد کولو ته جوړ کړل، چې دا فرياد خُدائ پاک ته ورسيږى. او هغۀ د ضرورتمندو خلقو فرياد واورېدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_28.mp3', '', 1761754199, 1761754199),
(40279, 'Job 34:29', 'Job', 34, 29, 'کۀ خُدائ پاک خاموش وى، نو څوک ورباندې اِعتراض کولے شى څۀ؟ کله چې هغه پناه شى، نو څوک يې ليدلے شى، کۀ هغه يو کس وى او کۀ قوم وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_29.mp3', '', 1761754199, 1761754199),
(40280, 'Job 34:30', 'Job', 34, 30, 'نو چې داسې د خُدائ پاک نه منکر خلق حکومت ونۀ کړى، او چې هغوئ خلق دوکه نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_30.mp3', '', 1761754199, 1761754199),
(40281, 'Job 34:31', 'Job', 34, 31, 'خلق خُدائ پاک ته ولې نۀ وائى چې، ”مونږ ګناه کړې ده، خو مونږ به نوره ګناه نۀ کوُو“؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_31.mp3', '', 1761754199, 1761754199),
(40282, 'Job 34:32', 'Job', 34, 32, 'يا، ”ما چې کومه بدعملى کړې وى نو هغه ما ته وښايه، کۀ ما غلطى کړې وى، نو فوراً به يې پرېږدم“؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_32.mp3', '', 1761754199, 1761754199),
(40283, 'Job 34:33', 'Job', 34, 33, 'خُدائ پاک به ستا د خوښې دپاره خپل اِنصاف پرېږدى؟ خو تا هغه رد کړے دے. دا زما نه بلکې ستا فېصله ده، مونږ ته اوس ووايه چې ستا خيال څۀ دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_33.mp3', '', 1761754199, 1761754199),
(40284, 'Job 34:34', 'Job', 34, 34, 'چې څوک پوهه لرى نو هغوئ به ما ته ووائى، او هغه عقلمند چې ما ته غوږ ږدى نو هغوئ به ووائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_34.mp3', '', 1761754199, 1761754199),
(40285, 'Job 34:35', 'Job', 34, 35, '”ايُوب د جهالت خبرې کوى، د هغۀ خبرې د کم عقلتوب نه ډکې دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_35.mp3', '', 1761754199, 1761754199),
(40286, 'Job 34:36', 'Job', 34, 36, 'ايُوب دې عدالت ته راوستلے شى او غټى نه غټه سزا دې ورکړے شى، ځکه چې هغه د بدعمله سړى په شان خبرې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_36.mp3', '', 1761754199, 1761754199),
(40287, 'Job 34:37', 'Job', 34, 37, 'ځکه چې هغه د سرکشۍ سره ګناه کوى، هغه ګستاخ دے، او هغه د خُدائ پاک خِلاف ډېرې خبرې کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job34_verse_37.mp3', '', 1761754199, 1761754199),
(40288, 'Isaiah 51:1', 'Isaiah', 51, 1, 'څښتن وایي: «ای هغو خلکو چې روان یئ د عدالت په لاره او یئ لټون کې د څښتن نو ماته غوږ ونیسئ فکر وکړئ د هغه ګټ په هکله چې جدا شوي یئ ترې فکر وکړئ د هغه کان په هکله چې راویستل شوي یئ ترې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_1.mp3', '', 1761754199, 1761754199),
(40289, 'Isaiah 51:2', 'Isaiah', 51, 2, 'فکر وکړئ د خپل نیکه ابراهیم په اړه او هم د ساره په اړه چې زېږولي یې یئ تاسو کله چې ما راوغوښت ابراهیم نو اولادونه یې نه وو خو ما ورکړ برکت هغه ته او هغه شو د اولادونو خاوند او اولاده مې ورته کړه ډېره زیاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_2.mp3', '', 1761754199, 1761754199),
(40290, 'Isaiah 51:3', 'Isaiah', 51, 3, 'زه به ورکړم تسلي صهیون ته او کنډوالې به د هغه جوړې کړم ټولې که څه هم چې ځمکه یې دښته ده خو زه به جوړ کړمه ترې باغ د هغه باغ په شان چې مې جوړ کړی ؤ عدن کې هلته وي به خوشحالي او خوښي هلته ویل کیږي به زما په خاطر د شکرانې او ثنا او صفت سندرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_3.mp3', '', 1761754199, 1761754199),
(40291, 'Isaiah 51:4', 'Isaiah', 51, 4, 'ای زما خلکو، ماته غوږ ونیسئ زه چې څه وایم ورته پام وکړئ زه به قومونو ته شریعت ورکړم زه به جاري کړمه خپل عدالت ترڅو رڼا شي ژوند د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_4.mp3', '', 1761754199, 1761754199),
(40292, 'Isaiah 51:5', 'Isaiah', 51, 5, 'زما عدالت او زما انصاف نژدې دی او راروانه ده زما ژغورنه زه به په خپله حکومت وکړم قومونو باندې لېرې هېوادونه انتظار کوي زما د راتلو په دې هیله دي چې وژغورم هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_5.mp3', '', 1761754199, 1761754199),
(40293, 'Isaiah 51:6', 'Isaiah', 51, 6, 'وکړئ نظر پورته اسمان ته او وګورئ لاندې ځمکې ته! ځکه چې ورک به له نظره شي اسمانونه د لوګي په شان ځمکه زړه به شي لکه کالیو په شان او ټول خلک به یې مړه شي د مچانو په شان خو زه به وژغورم تاسو د تل دپاره او نه لري پای زما عدالت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_6.mp3', '', 1761754199, 1761754199),
(40294, 'Isaiah 51:7', 'Isaiah', 51, 7, 'ای هغو خلکو چې پوهېږئ عدالت باندې نو ماته غوږ ونیسئ! او هغو خلکو چې زما شریعت ته یې ورکړی دی ځای په خپلو زړونو کې! کله چې څوک کړي سپکاوی ستاسو، نو مه وېرېږئ کله چې څوک درته ښکنځلې کوي، مه خپه کېږئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_7.mp3', '', 1761754199, 1761754199),
(40295, 'Isaiah 51:8', 'Isaiah', 51, 8, 'ځکه هغوی به وي هغو کالیو په شان چې وي خوړلي کوېو او هغو وړیو په شان چې خوړلي وي چنجیو خو وي به تلپاتې عدالت زما او ژغورنه به وي ټولو نسلونو دپاره»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_8.mp3', '', 1761754199, 1761754199),
(40296, 'Isaiah 51:9', 'Isaiah', 51, 9, 'راویښ شه، پاڅه ای څښتنه! د خپل قدرت څخه دې کار واخله او وژغوره مونږ لکه چې څنګه دې پخوا کړي وو دا ته وې چې دې ټوټې ټوټې کړه لویه بلا د سیند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_9.mp3', '', 1761754199, 1761754199),
(40297, 'Isaiah 51:10', 'Isaiah', 51, 10, 'دا هم ته وې چې بحیره دې کړله وچه یعنې هغه بحیره چې وه ډېره ژوره په ژورو د بحیرې کې دې کړه جوړه لاره ترڅو پرې تېر شي هغه خلک چې ژغورلي دي تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_10.mp3', '', 1761754199, 1761754199),
(40298, 'Isaiah 51:11', 'Isaiah', 51, 11, 'هغه خلک چې ژغورلي دي څښتن وبه رسیږي صهیون ته هغوی په خوشحالۍ سره او راستانه به شي صهیون ته په دې لاره د خوشحالۍ له سندرو سره د تاج په شان د هغوی په سر به وي خوشحالي تلپاتې د هغوی زړونه به شي ډک له خوشحالۍ نه او شي به له غم او له خفګانه خلاص', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_11.mp3', '', 1761754199, 1761754199),
(40299, 'Isaiah 51:12', 'Isaiah', 51, 12, 'څښتن وایي: «یوازې زه درکوم تسلي تاسو ته نو بیا وېرېږئ ولې له فاني انسانه چې د واښو په شان له منځه ځي زر؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_12.mp3', '', 1761754199, 1761754199),
(40300, 'Isaiah 51:13', 'Isaiah', 51, 13, 'ایا هېر کړی مو دی هغه څښتن، چې پیدا کړي یې یئ تاسو اسمانونه یې دي خپاره کړي او بنیاد یې ایښی دی د ځمکې؟ ولې په وېره کې تل ژوند تېروئ د هغو خلکو د غوسې له لاسه چې درباندې ظلم کوي څوک چې تیار دي تاسو له منځه یوسي؟ په تاسو نه کوي اغېزه نور د هغوی قهر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_13.mp3', '', 1761754199, 1761754199),
(40301, 'Isaiah 51:14', 'Isaiah', 51, 14, 'څوک چې بندیان دي زر به ازاد شي هغوی هغوی به نه مري په زندان کې او وږي به هم نه شي هېڅکله هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_14.mp3', '', 1761754199, 1761754199),
(40302, 'Isaiah 51:15', 'Isaiah', 51, 15, 'ځکه چې زه یم څښتن خدای ستاسو زه راولمه بحیره په څپو او غړمبوم څپې د هغه زما نوم دی مطلق قادر څښتن!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_15.mp3', '', 1761754199, 1761754199),
(40303, 'Isaiah 51:16', 'Isaiah', 51, 16, 'ما درکړی خپل کلام تاته او ساتلی مې یې د خپل لاس د سیوري لاندې ما خپاره کړي اسمانونه بنیاد مې ایښی دی د ځمکې او ما وویل صهیون ته: ‹ته یې قوم زما›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_16.mp3', '', 1761754199, 1761754199),
(40304, 'Isaiah 51:17', 'Isaiah', 51, 17, 'ای اورشلیمه، ته راویښ شه! ته راپاڅېږه او ودرېږه! تا د څښتن له لاسه څښلې د غضب ډکه پیاله چې یې درکړې وه د قهر په وخت کې هغه دې وڅښله تر وروستي څاڅکي پورې او اوس په لاره کوږ ووږ روان یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_17.mp3', '', 1761754199, 1761754199),
(40305, 'Isaiah 51:18', 'Isaiah', 51, 18, 'ستا چې څومره اولادونه زېږېدلي له هغو نه یو هم نشته چې ستا وکړي لارښوونه تا چې څومره اولادونه دي روزلي له هغو نه یو هم نشته چې تا ونیسي د لاسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_18.mp3', '', 1761754199, 1761754199),
(40306, 'Isaiah 51:19', 'Isaiah', 51, 19, 'دوه غبرګې بلاګانې نازل شوې دي په تا یعنې ورانی او تباهي، قحطي او جګړه داسې څوک نشته چې درته درکړي تسلي داسې څوک نشته چې درسره وکړي خواخوږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_19.mp3', '', 1761754199, 1761754199),
(40307, 'Isaiah 51:20', 'Isaiah', 51, 20, 'د هرې کوڅې په سر کې اولادونه ستا غورځیږي او پراته دي هغوی دي هغې هوسۍ په شان چې راګېر شوې وي په جال کې ځکه په هغو دی نازل شوی د څښتن غضب او هغوی رټلي دي ستا خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_20.mp3', '', 1761754199, 1761754199),
(40308, 'Isaiah 51:21', 'Isaiah', 51, 21, 'نو واورئ، ای د اورشلیم کړېدلو او بې وزله خلکو! که څه هم شراب مو نه دي څښلي خو نشه ښکارئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_21.mp3', '', 1761754199, 1761754199),
(40309, 'Isaiah 51:22', 'Isaiah', 51, 22, 'څښتن، ستاسو خدای کوي دفاع ستاسو او داسې وایي: «ګورئ، ما لېرې کړې ده پیاله د غضب ستاسو له لاسه د هغې پیالې په څښلو چې کاږه واږه ځئ تاسو نور به ونه څښئ تاسو دا پیاله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_22.mp3', '', 1761754199, 1761754199),
(40310, 'Isaiah 51:23', 'Isaiah', 51, 23, 'زه به ورکړم هغه چاته دا پیاله چا چې په تاسو باندې کړی ظلم هغه چا چې په کوڅو کې څملولئ تاسو او ایښودلې به یې پښې درباندې لکه چې ګرځي څوک په خاورو باندې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah51_verse_23.mp3', '', 1761754199, 1761754199);